<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><nav class="breadcrumb"><a href="<?=url('/admin/dashboard')?>">Dashboard</a><i data-lucide="chevron-right"></i><span>Announcements</span></nav><h1>Announcements</h1><p>Send official updates to students, parents, employees or teachers.</p></div></header>
<form class="module-card" method="post" enctype="multipart/form-data" action="<?=url('/admin/announcements')?>"><?=csrf_field()?><header class="module-card__header"><div><h2>New Announcement</h2><p>Published announcements remain in each recipient's announcement section.</p></div></header><div class="module-card__body"><div class="module-form-grid module-form-grid--three"><div class="module-field"><label>Title</label><input class="module-input" name="title" maxlength="180" required></div><div class="module-field"><label>Audience</label><select class="module-select" name="audience"><option value="all">Everyone</option><option value="students">Students</option><option value="parents">Parents</option><option value="employees">All employees</option><option value="teachers">Teachers only</option></select></div><div class="module-field"><label>Post as</label><select class="module-select" name="teacher_id"><option value="0">Administration (school announcement)</option><?php foreach($teachers as$t):?><option value="<?=(int)$t['id']?>"><?=e($t['name'])?> (teacher announcement)</option><?php endforeach?></select><small>Choosing a teacher shows it under Teacher Announcements in that teacher's name.</small></div><div class="module-field"><label>Class</label><select class="module-select" name="class_id"><option value="0">All classes</option><?php foreach($classes as$c):?><option value="<?=(int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach?></select><small>A single class goes to its students and parents only.</small></div><div class="module-field"><label>Status</label><select class="module-select" name="status"><option value="published">Published</option><option value="draft">Draft</option></select></div><div class="module-field field--wide"><label>Message</label><textarea class="module-textarea" name="message" rows="5" required></textarea></div><div class="module-field"><label>Announcement image</label><input class="module-input" type="file" name="image" accept=".jpg,.jpeg,.png"><small>Optional JPG or PNG, maximum 5 MB.</small></div><div class="module-field"><label>Publish at</label><input class="module-input" type="datetime-local" name="publish_at" value="<?=date('Y-m-d\TH:i')?>"></div><div class="module-field"><label>Expires at <small>(optional)</small></label><input class="module-input" type="datetime-local" name="expires_at"></div><label class="checkbox-row"><input type="checkbox" name="show_popup" value="1"><span><strong>Show as popup</strong><small>Recipients see it once per browser session and can still find it in Announcements.</small></span></label><?php if(!empty($smsAvailable)):?><div class="field--wide" data-sms-announce data-count-url="<?=e(url('/admin/sms/count'))?>"><label class="checkbox-row"><input type="checkbox" name="send_sms" value="1" data-sms-announce-toggle><span><strong>Also send via SMS</strong><small>Queues one SMS per recipient for the institute's SMS gateway. Only for published announcements.</small></span></label><div class="module-form-grid module-form-grid--three" data-sms-announce-fields hidden><div class="module-field"><label>SMS recipients</label><select class="module-select" name="sms_audience" data-sms-announce-audience><option value="parents">Parents / guardians</option><option value="students">Students</option><option value="staff">Staff</option></select><small>If a class is selected above, only that class's students or parents are messaged.</small></div><div class="module-field field--wide"><label>SMS text <small>(optional)</small></label><textarea class="module-textarea" name="sms_text" rows="3" maxlength="1000" placeholder="Leave empty to send the title using the Announcement SMS template."></textarea></div><p class="field--wide" data-sms-announce-count style="margin:0;font-size:12px;color:var(--text-muted)"></p></div></div><?php endif?></div></div><footer class="module-card__footer"><button class="btn btn--primary">Publish Announcement</button></footer></form>
<?php $groups=['School Announcements'=>array_filter($announcements,static fn($a)=>empty($a['teacher_id'])),'Teacher Announcements'=>array_filter($announcements,static fn($a)=>!empty($a['teacher_id']))];foreach($groups as$heading=>$rows):$isTeacher=$heading==='Teacher Announcements';?><section class="module-card"><header class="module-card__header"><h2><?=e($heading)?></h2></header><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Publish</th><th>Title</th><?php if($isTeacher):?><th>Teacher</th><th>Posted by</th><?php endif?><th>Class</th><th>Audience</th><th>Popup</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as$a):?><tr><td><?=e($a['publish_at'])?></td><td><strong><?=e($a['title'])?></strong></td><?php if($isTeacher):?><td><?=e($a['teacher_name']??'Removed teacher')?></td><td><?=!empty($a['by_teacher'])?'Teacher':e('Admin ('.($a['author_name']??'').')')?></td><?php endif?><td><?=e($a['class_name']??'All classes')?></td><td><?=e(ucfirst($a['audience']))?></td><td><?=$a['show_popup']?'Yes':'No'?></td><td><span class="status-badge"><?=e(ucfirst($a['status']))?></span></td><td><form method="post" action="<?=url('/admin/announcements/'.$a['id'].'/delete')?>" onsubmit="return confirm('Delete this announcement?')"><?=csrf_field()?><button class="class-action-button class-action-button--danger" aria-label="Delete announcement"><i data-lucide="trash-2"></i></button></form></td></tr><?php endforeach?><?php if(!$rows):?><tr><td colspan="<?=$isTeacher?9:7?>"><div class="compact-empty"><h3>No <?=e(strtolower($heading))?> yet</h3></div></td></tr><?php endif?></tbody></table></div></div></section><?php endforeach?></div></div></main>
